using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Authorization;using System.Security.Claims;using NutriPlate.Api.Services;
namespace NutriPlate.Api.Controllers;
[ApiController][Authorize][Route("api/nutrition")]
public class NutritionController(NutriPlateService service):ControllerBase {
 [HttpGet("daily/{date}")] public async Task<IActionResult> Daily(string date,CancellationToken ct){if(!DateOnly.TryParse(date,out _))return BadRequest(new{error="Date must use YYYY-MM-DD format."});var plans=await service.GetPlans(User.FindFirstValue(ClaimTypes.NameIdentifier)!,ct);var meals=plans.SelectMany(p=>p.Meals).Where(m=>m.Date==date).ToList();return Ok(new{date,mealCount=meals.Count,calories=meals.Sum(m=>m.Nutrition.Calories*m.Servings),protein=meals.Sum(m=>m.Nutrition.Protein*m.Servings),carbohydrates=meals.Sum(m=>m.Nutrition.Carbohydrates*m.Servings),fat=meals.Sum(m=>m.Nutrition.Fat*m.Servings),estimated=true});}
 [HttpGet("weekly")] public async Task<IActionResult> Weekly(CancellationToken ct){var plans=await service.GetPlans(User.FindFirstValue(ClaimTypes.NameIdentifier)!,ct);var meals=plans.SelectMany(p=>p.Meals).ToList();return Ok(new{mealCount=meals.Count,calories=meals.Sum(m=>m.Nutrition.Calories*m.Servings),protein=meals.Sum(m=>m.Nutrition.Protein*m.Servings),carbohydrates=meals.Sum(m=>m.Nutrition.Carbohydrates*m.Servings),fat=meals.Sum(m=>m.Nutrition.Fat*m.Servings),estimated=true});}
 [HttpGet("recipe/{id}")] public async Task<IActionResult> Recipe(string id,[FromQuery]int servings=1,CancellationToken ct=default){if(servings<1||servings>20)return BadRequest(new{error="Servings must be between 1 and 20."});var r=await service.GetRecipe(id,ct);if(r==null)return NotFound();return Ok(new{recipeId=id,servings,calories=r.Nutrition.Calories*servings,protein=r.Nutrition.Protein*servings,carbohydrates=r.Nutrition.Carbohydrates*servings,fat=r.Nutrition.Fat*servings,estimated=true});}
}
